// Parser la réponse Gemini et préparer les données
const items = $input.all();
const results = [];

for (const item of items) {
  const originalData = item.json;
  let analysis;

  try {
    // Extraire le JSON de la réponse Gemini
    let responseText = originalData.text || originalData.output || '';

    // Nettoyer le texte (enlever les ```json si présent)
    responseText = responseText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

    analysis = JSON.parse(responseText);
  } catch (e) {
    // Fallback si parsing échoue
    analysis = {
      city: null,
      city_confidence: 'low',
      landmark: null,
      scene_description: 'unknown',
      quality: { sharpness: 5, composition: 5, lighting: 5, visual_interest: 5, overall: 5 },
      is_duplicate_candidate: false,
      is_blurry: false,
      suggested_filename: 'Photo_Non_Identifiee'
    };
  }

  // Calculer le score de qualité global (0-100)
  const qualityScore = analysis.quality ? 
    (analysis.quality.sharpness + analysis.quality.composition + 
     analysis.quality.lighting + analysis.quality.visual_interest + 
     analysis.quality.overall) * 2 : 50;

  // Générer le nom de fichier final
  const city = analysis.city || 'Non_Classe';
  const descriptor = analysis.suggested_filename || `${city}_Photo`;
  const timestamp = Date.now();
  const finalFilename = `${descriptor}_${timestamp.toString().slice(-6)}`;

  // Déterminer si la photo doit être gardée
  const shouldKeep = !analysis.is_blurry && qualityScore >= 40;

  results.push({
    json: {
      originalId: originalData.id || originalData.fileId,
      originalName: originalData.name || originalData.fileName,
      city: city,
      cityConfidence: analysis.city_confidence,
      landmark: analysis.landmark,
      sceneDescription: analysis.scene_description,
      qualityScore: qualityScore,
      qualityDetails: analysis.quality,
      isBlurry: analysis.is_blurry,
      isDuplicateCandidate: analysis.is_duplicate_candidate,
      suggestedFilename: finalFilename,
      shouldKeep: shouldKeep,
      analysisRaw: analysis
    },
    binary: item.binary
  });
}

return results;

// Marquer les photos à supprimer/exclure
const item = $input.item;
return {
  json: {
    ...item.json,
    action: 'exclude',
    reason: item.json.isBlurry ? 'blurry' : 'low_quality'
  }
};

// Collecter toutes les photos valides pour regroupement par ville
const item = $input.item;
return {
  json: {
    ...item.json,
    action: 'organize'
  },
  binary: item.binary
};

// Regrouper les photos par ville et préparer la structure
const allItems = $input.all();
const photosByCity = {};
const excludedPhotos = [];
const allValidPhotos = [];

for (const item of allItems) {
  const data = item.json;

  if (data.action === 'exclude') {
    excludedPhotos.push(data);
    continue;
  }

  const city = data.city || 'Non_Classe';

  if (!photosByCity[city]) {
    photosByCity[city] = [];
  }

  photosByCity[city].push({
    originalId: data.originalId,
    originalName: data.originalName,
    suggestedFilename: data.suggestedFilename,
    qualityScore: data.qualityScore,
    city: city,
    landmark: data.landmark,
    sceneDescription: data.sceneDescription
  });

  allValidPhotos.push({
    originalId: data.originalId,
    originalName: data.originalName,
    suggestedFilename: data.suggestedFilename,
    qualityScore: data.qualityScore,
    city: city
  });
}

// Sélectionner les 20 meilleures photos
const topPhotos = allValidPhotos
  .sort((a, b) => b.qualityScore - a.qualityScore)
  .slice(0, 20);

return [
  {
    json: {
      photosByCity: photosByCity,
      cities: Object.keys(photosByCity),
      topPhotos: topPhotos,
      excludedCount: excludedPhotos.length,
      totalValid: allValidPhotos.length,
      summary: {
        totalProcessed: allItems.length,
        keptPhotos: allValidPhotos.length,
        excludedPhotos: excludedPhotos.length,
        citiesFound: Object.keys(photosByCity).length
      }
    }
  }
];

// Créer un item par ville pour la création de dossiers
const data = $input.first().json;
const cities = data.cities || [];
const photosByCity = data.photosByCity || {};

return cities.map(city => ({
  json: {
    cityName: city,
    folderName: city.replace(/_/g, ' '),
    photos: photosByCity[city] || [],
    photoCount: (photosByCity[city] || []).length
  }
}));

// Préparer les opérations de déplacement/renommage pour chaque photo
const cityData = $('Séparer par Ville').item.json;
const folderId = $json.id; // ID du dossier créé
const photos = cityData.photos || [];

return photos.map((photo, index) => ({
  json: {
    fileId: photo.originalId,
    newName: `${photo.suggestedFilename}.jpg`,
    destinationFolderId: folderId,
    index: index + 1
  }
}));

// Récupérer les top 20 photos depuis le node de groupement
const groupData = $('Grouper par Ville').first().json;
const topPhotos = groupData.topPhotos || [];

return [
  {
    json: {
      topPhotos: topPhotos,
      count: topPhotos.length
    }
  }
];

// Préparer les opérations de copie pour les meilleures photos
const topPhotosData = $('Récupérer Top 20').first().json;
const bestFolderId = $json.id; // ID du dossier "Meilleures photos"
const topPhotos = topPhotosData.topPhotos || [];

return topPhotos.map((photo, index) => ({
  json: {
    fileId: photo.originalId,
    destinationFolderId: bestFolderId,
    newName: `${String(index + 1).padStart(2, '0')}_${photo.suggestedFilename}.jpg`,
    rank: index + 1,
    qualityScore: photo.qualityScore
  }
}));

// Générer le rapport final
const groupData = $('Grouper par Ville').first().json;

const report = {
  status: 'completed',
  summary: groupData.summary,
  citiesOrganized: groupData.cities,
  topPhotosSelected: groupData.topPhotos.length,
  message: `Organisation terminée avec succès!
    - ${groupData.summary.totalProcessed} photos analysées
    - ${groupData.summary.keptPhotos} photos conservées
    - ${groupData.summary.excludedPhotos} photos exclues (floues/mauvaise qualité)
    - ${groupData.summary.citiesFound} villes identifiées
    - ${groupData.topPhotos.length} meilleures photos sélectionnées`
};

return [{ json: report }];
